(* [comment removed for export] *)
Definition peof_ctx (m m1 : mem) (sp s0v s1v s2v s3v rav : word) (P E lo shi : Z) (c : pcore) (pad7 pad2 ej j24 : list byte) (g : bool) : Prop :=
  rw_cells bsegs m1 (bv_unsigned sp + -64) [CB 24 j24]
  /\ rw_cells bsegs m1 (bv_unsigned sp + -40) [C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells bsegs m1 P (ParserCoreCells c pad7 pad2)
  /\ rw_cells bsegs m1 E [CB 24 ej]
  /\ stk bsegs m1 lo (bv_unsigned sp + -64)
  /\ munch (body_W lo sp P E) m m1 /\ wmono bsegs m m1 /\ mem_inv bsegs m1
  /\ munch [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24)]%Z m m1
  /\ AHttpCat m g /\ st_side m P E lo shi.

Definition peof_exit_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (loc : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch (body_W lo sp P E) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells bsegs m' E (ErrCodeCells (EC_http_loc HE_PARTIAL_MESSAGE loc))
    /\ AHttpCat m' true /\ AXStatics2 m'
    /\ ACONST m' /\ stack0 m' lo shi.

(* [comment removed for export] *)
Definition peof_exit_stmt (pc loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s1x s2v s3v s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo shi : Z) (c : pcore) (pad7 pad2 ej j24 : list byte) (g : bool),
  peof_ctx m m1 sp s0v s1v s2v s3v ra P E lo shi c pad7 pad2 ej j24 g ->
  st_pure PEOF_STACK sp P E lo shi ->
  (pc = 0xd0cf8 -> s3x = wz 2) ->
  evt bsegs (peof_exit_post ra sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo shi c pad7 pad2 loc m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz E) s1x a0x a1 a2 a3 a4 a5 a6 a7
              (wz 2147450880) s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom bsegs)).

Lemma ec_loc_cells : forall m E e loc, 1 <= e < 2^31 ->
  rw_cells bsegs m E [CB 16 (le8 (Z_to_bv 64 e) ++ le8 (Z_to_bv 64 AG_HTTP_CAT)); C8 (Z_to_bv 64 (loc + 1))] ->
  rw_cells bsegs m E (ErrCodeCells (EC_http_loc e loc)).
Proof.
  intros m E e loc He V.
  eapply rw_cells_reshape; [exact V| cbn; repeat split; reflexivity
    | unfold ErrCodeCells, EC_http_loc, ec_make_loc, wz; cbn [ec_val ec_cat ec_flags cells_bytes cbytes app];
      replace (e =? 0) with false by (symmetry; apply Z.eqb_neq; lia);
      rewrite ?app_nil_r, <- ?app_assoc; reflexivity].
Qed.

Local Ltac peof_exit_script loc :=
  unfold peof_exit_stmt;
  intros rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s1x s2v s3v s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         F fc m m1 P E lo shi c pad7 pad2 ej j24 g;
  intros CTX PURE S3X;
  destruct CTX as (FRlo & FRhi & PC & EC & ST & MU & WM & MI & MUq & HC & SIDE);
  pose proof (body_pwin _ _ _ _ _ _ PURE) as FW;
  pose proof PURE as PURE';
  destruct PURE' as (LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI);
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof (aapp_bounds _ 80 APP ltac:(lia)) as (PB1 & PB2 & PB3 & PB4 & PB5);
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof (body_cat_now _ _ _ _ _ _ _ HC MUq WM CEIL APP APE) as HC1;
  clear MUq HC;
  assert (D8 : (bv_unsigned sp + -64) mod 8 = 0) by (clear - SPAL; Z.div_mod_to_equations; lia);
  clear PAL SPAL AF2 AF3 EB5 PB5; hydeL DPE; hydeL EAL; hydeL D8;
  unfold body_W, PEOF_STACK, AASSIGN_STACK, AINTRIN_STACK, AG_HTTP_CAT, AAPP_HI, AIMG_TOP in *;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold wz in *;
  first [ rewrite (S3X eq_refl) | idtac ]; clear S3X;
  (* [comment removed for export] *)
  steps_to 0xbaeb4%Z;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let SDc := fresh "SDc" in let AS := fresh "AS" in
    pose proof (pside2_transport _ _ mc _ _ _ _ SIDE MU WM FW) as SDc;
    pose proof ASSIGNA as AS;
    unfold aassignA_stmt, aassign_stmt, aassign_post, aassign_W, P_A_EC_CTOR_HTTP, AG_HTTP_CAT, AASSIGN_STACK, AINTRIN_STACK in AS;
    callZc (AS _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ (bv_unsigned sp + -64) 2 lo shi g j24) (clear FRlo ST AS);
    [ exact FRlo | exact HC1 | exact (pside2_statics _ _ _ _ _ SDc) | rewrite ?unsigned_lit by lia; exact ST
    | rewrite ?unsigned_lit by lia; lia | lia | rewrite ?unsigned_lit by lia; lia | lia
    | exact D8 | lia
    | exact MI | exact (pside2_aconst _ _ _ _ _ SDc) | exact (pside2_stack0 _ _ _ _ _ SDc) | rewrite ?unsigned_lit by lia; lia | ];
    clear SDc HC1 D8
  end;
  lazymatch goal with
  | TMP2 : rw_cells _ ?m2 (bv_unsigned sp + -64) (ErrCodeCells _), HC2 : AHttpCat ?m2 true,
    AC2 : ACONST ?m2, SK2 : stack0 ?m2 lo shi, ST2 : stk _ ?m2 lo _, MU' : munch _ m ?m2, WM' : wmono _ m ?m2 |- _ =>
    let SD2 := fresh "SD2" in let KF := fresh "KF" in
    let TMPa := fresh "TMPa" in let TMPb := fresh "TMPb" in let ECa := fresh "ECa" in let ECb := fresh "ECb" in
    let SRC := fresh "SRC" in let MU3 := fresh "MU3" in let WM3 := fresh "WM3" in
    pose proof (pside2_transport _ _ m2 _ _ _ _ SIDE ltac:(unfold AG_HTTP_CAT; exact MU') WM' FW) as SD2;
    (* [comment removed for export] *)
    unfold ErrCodeCells, EC_http, ec_make in TMP2; cbn [ec_val ec_cat ec_flags Z.eqb] in TMP2; unfold AG_HTTP_CAT, wz in TMP2;
    step; step; if_cases KF; zify_cond KF; [exfalso; clear - KF; lia|];
    (* [comment removed for export] *)
    zstep; change (Z.land 3 1) with 1; step; step; zstep;
    replace (Z.lor 1 loc) with (loc + 1) by (vm_compute; reflexivity);
    (* [comment removed for export] *)
    step; step; step; step;
    split_frameA TMP2 [C8 (Z_to_bv 64 2); C8 (Z_to_bv 64 6684368)] [C8 (Z_to_bv 64 3)] TMPa TMPb;
    pose proof (rw_cells_bytes_at _ _ _ _ TMPa) as SRC; cbn [cells_bytes cbytes app] in SRC; rewrite app_nil_r in SRC;
    destruct (rw_cells_CB_split bsegs _ E 24 16 ej EC ltac:(clear; lia)) as [ECa ECb]; clear EC;
    cbn [Nat.sub] in ECb; change (Z.of_nat 16) with 16 in ECb;
    pose proof (munch_refl [(lo, bv_unsigned sp); (E, E + 24)]%Z m2) as MU3; pose proof (wmono_refl bsegs m2) as WM3;
    callZc (asan_memcpy_specZ MEMCPY _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ (bv_unsigned sp + -64) E (bv_unsigned sp + -64) 16
              (le8 (Z_to_bv 64 2) ++ le8 (Z_to_bv 64 6684368)) (firstn 16 ej) lo)
           (clear ECa ST2 SRC);
    [ exact SRC | rewrite length_app, !length_le8; reflexivity | exact ECa
    | right; clear - EB2 CEIL LO; lia | clear; lia | clear - LO CEIL AF1; lia | clear - EB4; lia
    | eapply stack0_accessible; [exact SK2| clear - LO; lia| clear; lia| clear - SHI; lia]
    | eapply accessible_sub; [exact (pside2_acc _ _ _ _ _ E 24 SD2 ltac:(ps_in))| clear; lia| clear; lia| clear; lia]
    | eapply stack0_shvis; [exact SK2| clear - LO; lia| clear; lia| clear - SHI; lia]
    | eapply shvis_sub; [exact (pside2_shvis _ _ _ _ _ E 24 SD2 ltac:(ps_in))| clear - EB4; lia| clear; lia| clear; lia| clear; lia| clear - EB4; lia]
    | eapply stack0_in_app_mem; [exact SK2| clear - LO; lia| clear - SHI; lia]
    | eapply aapp_in_app_mem; [exact APE| clear; lia| clear; lia]
    | eapply aconst_ok_aapp; [exact APE| clear; lia| clear; lia]
    | exact ST2 | exact CEIL | clear - LO; lia | clear - SPR; lia
    | left; clear - EB2 CEIL; lia | right; clear; lia
    | assumption | exact AC2 | ];
    clear SK2 AC2 SD2;
    lazymatch goal with
    | DST3 : rw_cells _ ?m3 E [CB _ _], MU'' : munch _ m ?m3, WM'' : wmono _ m ?m3 |- _ =>
      let SD3 := fresh "SD3" in let RD := fresh "RD" in let HC3 := fresh "HC3" in
      pose proof (pside2_transport _ _ m3 _ _ _ _ SIDE ltac:(unfold AG_HTTP_CAT; exact MU'') WM'' FW) as SD3;
      (* [comment removed for export] *)
      step;
      pose proof (accessible_read0_sr m3 E 24 (E + 16) (pside2_acc _ _ _ _ _ E 24 SD3 ltac:(ps_in)) ltac:(clear; lia)
                    ltac:(clear - EAL; unfold hideL in EAL; Z.div_mod_to_equations; lia) ltac:(clear; lia)) as RD;
      shchk_fast RD; clear SD3;
      st1;
      (* [comment removed for export] *)
      step; step; step; step; step;
      join_frameA TMPa TMPb (bv_unsigned sp + -64); join_frameA TMPa FRhi (bv_unsigned sp + -64);
      step;
      lazymatch goal with ST3 : stk _ _ lo (bv_unsigned sp + -64) |- _ => release_frame TMPa ST3 (bv_unsigned sp) end;
      step;
      lazymatch goal with
      | ECb' : rw_cells _ ?m4 (E + 16) [C8 _], MU4 : munch _ m ?m4, WM4 : wmono _ m ?m4, MU3' : munch _ m2 ?m4, WM3' : wmono _ m2 ?m4 |- _ =>
        let SD4 := fresh "SD4" in let HC4 := fresh "HC4" in
        pose proof (pside2_transport _ _ m4 _ _ _ _ SIDE ltac:(unfold body_W, AG_HTTP_CAT; exact MU4) WM4 FW) as SD4;
        assert (HC4 : AHttpCat m4 true)
          by (eapply AHttpCat_transport; [exact HC2| exact MU3'| exact WM3'| |];
              cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD; clear - AF1 CEIL LO EB1; repeat split; lia);
        pose proof (pside2_aconst _ _ _ _ _ SD4); pose proof (pside2_stack0 _ _ _ _ _ SD4); pose proof (pside2_statics2 _ _ _ _ _ SD4);
        join_frameA DST3 ECb' E;
        apply (ec_loc_cells _ _ 2 loc ltac:(clear; lia)) in DST3;
        unfold peof_exit_post;
