(* [comment removed for export] *)
(* [comment removed for export] *)

Definition pb1_W (lo : Z) (sp : word) (E : Z) : list (Z * Z) := [(lo, bv_unsigned sp); (E, E + 24)]%Z.
Definition pb2_W (lo : Z) (sp : word) (P IN E : Z) : list (Z * Z) := [(lo, bv_unsigned sp); (P, P + 80); (IN, IN + 8); (E, E + 24)]%Z.

Lemma pb1_pwin : forall B sp P IN E lo shi, stin_pure B sp P IN E lo shi -> Forall pwin (pb1_W lo sp E).
Proof.
  intros B sp P IN E lo shi ((LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI) & ILO & IHI & IAL).
  unfold pb1_W. repeat apply Forall_cons; [| | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
Qed.
Lemma pb2_pwin : forall B sp P IN E lo shi, 0 <= B -> stin_pure B sp P IN E lo shi -> Forall pwin (pb2_W lo sp P IN E).
Proof.
  intros B sp P IN E lo shi HB ((LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI) & ILO & IHI & IAL).
  unfold pb2_W. repeat apply Forall_cons; [| | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - eapply pwin_aapp; [exact APP| clear; lia| clear; lia].
  - apply pwin_stack. clear - CEIL LO ILO HB. lia.
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
Qed.

